def find_Rotations(s: str) -> int:
    """Return the minimum number of rotations needed to get the same string.

    Args:
        s: A string consisting of lowercase English letters.

    Returns:
        The minimum number of rotations needed to get the same string.
    """
    if not s:
        return 0
    if len(s) == 1:
        return 1

    # Count occurrences of each character
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    # Find the minimum rotations
    min_rotations = float('inf')
    for char, count in char_counts.items():
        if count < min_rotations:
            min_rotations = count

    return min_rotations

