def longest_palindromic_subsequence(s: str) -> int:
    """Return the length of the longest palindromic subsequence in the input string.

    Args:
        s: A string (can be empty).

    Returns:
        The length of the longest palindromic subsequence.

    Raises:
        ValueError: If the input string is empty.
    """
    if not s:
        raise ValueError("Input string cannot be empty.")

    n = len(s)
    dp = [1] * n
    dp[0] = 0  # Empty subsequence is always a valid subsequence

    for i in range(1, n):
        for j in range(i):
            if s[i] == s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

