def filter_data(data):
    """
    Filter students that have height and weight above the minimum.

    Args:
        data: A dictionary with keys 'Cierra Vega', 'Alden Cantrell', 'Kierra Gentry', 'Pierre Cox', 'Cierra Vega'.

    Returns:
        A new dictionary with keys 'Cierra Vega', 'Alden Cantrell', 'Kierra Gentry', 'Pierre Cox', 'Cierra Vega'.
    """
    if not data:
        return {}

    # Sort by height descending, then by weight descending
    sorted_data = sorted(data.items(), key=lambda x: x[1], reverse=True)

    # Filter by height and weight
    filtered_data = {}
    for key, value in sorted_data:
        if key in data and value > data[key][1]:
            filtered_data[key] = value

    return filtered_data

