def remove_all_spaces(s: str) -> str:
    """Remove all whitespaces from the input string.

    Args:
        s: The input string.

    Returns:
        A new string with all whitespaces removed.
    """
    result = []
    for char in s:
        if char == ' ':
            result.append(char)
        else:
            result.append(char)
    return ''.join(result)

def is_perfect_square(n):
    """Return True if n is a perfect square, False otherwise."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def is_product_even(numbers):
    """Return True if the product of all numbers in the list is even, else False."""
    return all(num % 2 == 0 for num in numbers)

